fn quoted_by(quote: char, input: Span) -> IResult<Token> {
    let (rest, inner) = delimited(
        cut(char(quote)),
        take_till(|c| c == quote),
        cut(char(quote)),
    )(input)?;

    // Check if there are escaped quotes inside and handle them
    // We need to verify if the original content had escaped quotes
    // Since take_till stops at the first unescaped quote, we need to re-parse properly
    // Actually, the above approach is flawed for escaped quotes.
    // Let's implement a proper parser that handles escaped quotes.

    // Reset and implement correctly
    let mut cursor = input.as_ref();
    let quote_byte = quote as u8;

    // Find the closing quote, handling escapes
    let mut escape = false;
    let mut end_index = None;
    for (i, &b) in cursor.iter().enumerate() {
        if b == b'\\' {
            escape = !escape;
            continue;
        }
        if escape {
            escape = false;
            continue;
        }
        if b == quote_byte {
            end_index = Some(i);
            break;
        }
    }

    if let Some(end) = end_index {
        let content = input.slice(1..end);
        let result = unescape(content, quote);
        let rest = input.slice(end + 1..);
        Ok((rest, Token::String(result)))
    } else {
        Err(nom::Err::Error(Error::new(
            input,
            ErrorKind::Expected {
                kind: ExpectedValueKind::String,
            },
        )))
    }
}
