pub fn match_pattern(pattern: &str, str: &str) -> PatternMatch {
    if pattern == str {
        return PatternMatch::Match;
    }

    // Check if pattern is a prefix of str with a dot separator (e.g., pattern="toto", str="toto.titi")
    if str.starts_with(pattern) {
        let remaining = &str[pattern.len()..];
        if remaining.starts_with('.') {
            return PatternMatch::Parent;
        }
    }

    // Check if pattern is a suffix of str with a dot separator (e.g., pattern="titi", str="toto.titi")
    if str.ends_with(pattern) {
        let prefix_len = str.len() - pattern.len();
        if prefix_len > 0 && &str[prefix_len - 1..prefix_len] == "." {
            return PatternMatch::Match;
        }
    }

    // Check for wildcard patterns (containing '*')
    if pattern.contains('*') {
        // Split pattern by '*' and check each segment
        let segments: Vec<&str> = pattern.split('*').collect();
        if segments.len() == 1 {
