    // Convert the bounds to bytes for the search
    let left_bytes = match left {
        Bound::Included(v) => {
            let mut buf = Vec::new();
            BoundCodec::bytes_encode(v, &mut buf).map_err(|e| heed::Error::Encoding(e))?;
            Bound::Included(buf.as_slice())
        }
        Bound::Excluded(v) => {
            let mut buf = Vec::new();
            BoundCodec::bytes_encode(v, &mut buf).map_err(|e| heed::Error::Encoding(e))?;
            Bound::Excluded(buf.as_slice())
        }
        Bound::Unbounded => Bound::Unbounded,
    };

    let right_bytes = match right {
        Bound::Included(v) => {
            let mut buf = Vec::new();
            BoundCodec::bytes_encode(v, &mut buf).map_err(|e| heed::Error::Encoding(e))?;
            Bound::Included(buf.as_slice())
        }
        Bound::Excluded(v) => {
            let mut buf = Vec::new();
            BoundCodec::bytes_encode(v, &mut buf).map_err(|e| heed::Error::Encoding(e))?;
            Bound::Excluded(buf.as_slice())
        }
        Bound::Unbounded => Bound::Unbounded,
    };

    // Remap the database to use BytesRefCodec for the key codec and FacetGroupLazyValueCodec for value
    let db_remapped = db.remap_key_type::<FacetGroupKeyCodec<BytesRefCodec>>().remap_data_type::<FacetGroupLazyValueCodec>();

    // Create the search context
    let mut search = FacetRangeSearch {
        rtxn,
        db: db_remapped,
        field_id,
        left: left_bytes,
        right: right_bytes,
        universe,
        docids,
    };

    // Determine the starting point for the search
    let starting_left_bound = match left {
        Bound::Included(_) | Bound::Excluded(_) => {
            // We need to find the first key >= the left bound
            // Since we don't have a direct way to get the key, we start from the beginning of the field
            // and let the iterator handle it
            &[]
        }
        Bound::Unbounded => &[],
    };

    // Determine the rightmost bound for the search
    let rightmost_bound = match right {
        Bound::Included(_) | Bound::Excluded(_) => right_bytes,
        Bound::Unbounded => Bound::Unbounded,
    };

    // Get the size of the top level group
    let top_key = FacetGroupKey {
        field_id,
        level: highest_level,
        left_bound: starting_left_bound,
    };

    let mut iter = db_remapped.range(rtxn, &(top_key..))?;
    let first = iter.next();
    let group_size = if let Some(Ok((_, value))) = first {
        value.size as usize
    } else {
        return Ok(());
    };

    // Run the recursive search
    search.run(highest_level, starting_left_bound, rightmost_bound, group_size)?;

    Ok(())
}
