    use heed::BytesDecode;

    let highest_level = get_highest_level(rtxn, db, field_id)?;
    let last_value = get_last_facet_value::<BytesRefCodec, _>(rtxn, db, field_id)?;

    let mut stack: Vec<(
        RoaringBitmap,
        std::iter::Take<
            heed::RoRevRange<'t, FacetGroupKeyCodec<BytesRefCodec>, FacetGroupValueCodec>,
        >,
        Bound<&'t [u8]>,
    )> = Vec::new();

    if let Some(last_val) = last_value {
        let mut prefix = vec![];
        prefix.extend_from_slice(&field_id.to_be_bytes());
        prefix.push(0);
        prefix.push(0);

        let iter = db.remap_types::<Bytes, DecodeIgnore>().range(prefix)?;
        let mut take_iter = iter.rev();
