            let key = FacetGroupKeyCodec::<BytesRefCodec>::bytes_decode(key)?;
            if key.left_bound <= last_val {
                stack.push((candidates, take_iter.skip(1).take(1), std::ops::Bound::Unbounded));
            }
        }
    }

