        if self.value_kind == ValueKind::Single {
            let path = ValuePath::from_path(&[]);
            let extracted = extract_value::<T>(&[], &mut value).with_context(|kind| {
                ExtractionError {
                    kind,
                    context: ExtractionErrorContext::SingleValue(path),
                }
            })?;
            return Ok(vec![extracted]);
        }

        // Handle array extraction based on the stored array paths
        let array_paths = match &self.value_kind {
            ValueKind::Array(paths) => paths,
            ValueKind::Single => unreachable!(), // Already handled above
        };

        for array_path in array_paths {
